CREATE TABLE model_turn_decisions (pool_id BIGINT NOT NULL REFERENCES model_turn_pools(id) ON DELETE CASCADE, request_fingerprint VARCHAR(71) NOT NULL, generation BIGINT NOT NULL, decision VARCHAR(32) NOT NULL, diagnostic VARCHAR(128), recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (pool_id, request_fingerprint, generation), CONSTRAINT model_turn_decisions_fingerprint CHECK (request_fingerprint ~ '^sha256:[0-9a-f]{64}$'), CONSTRAINT model_turn_decisions_generation CHECK (generation > 0), CONSTRAINT model_turn_decisions_kind CHECK (decision IN ('shadow_permit','enforce_admitted','wait','rejected')), CONSTRAINT model_turn_decisions_diagnostic CHECK (diagnostic IS NULL OR diagnostic ~ '^[a-z0-9_-]{1,128}$'));
